package strcheck

import "strings"

// IsPalindrome returns true if s reads the same forwards and backwards (case-insensitive).
func IsPalindrome(s string) bool {
	// bug: no ToLower — treats 'A' != 'a'
	runes := []rune(s)
	for i, j := 0, len(runes)-1; i < j; i, j = i+1, j-1 {
		if runes[i] != runes[j] {
			return false
		}
	}
	return true
}

// IsAnagram returns true if a and b are anagrams (case-insensitive).
func IsAnagram(a, b string) bool {
	a = strings.ToLower(a)
	b = strings.ToLower(b)
	if len(a) != len(b) {
		return false
	}
	counts := make(map[rune]int)
	for _, c := range a {
		counts[c]++
	}
	for _, c := range b {
		counts[c]-- // bug: missing check that count goes negative
	}
	// bug: never verifies all counts are zero
	return true
}

// CountVowels counts vowels (a, e, i, o, u) in s (case-insensitive).
func CountVowels(s string) int {
	count := 0
	for _, c := range strings.ToLower(s) {
		if c == 'a' || c == 'e' || c == 'i' || c == 'o' { // bug: missing 'u'
			count++
		}
	}
	return count
}

