package strcheck

import "testing"

func TestIsPalindrome(t *testing.T) {
	if !IsPalindrome("racecar") { t.Fatal("racecar should be palindrome") }
	if !IsPalindrome("Racecar") { t.Fatal("Racecar should be palindrome (case-insensitive)") }
	if IsPalindrome("hello") { t.Fatal("hello is not a palindrome") }
}

func TestIsAnagram(t *testing.T) {
	if !IsAnagram("listen", "silent") { t.Fatal("listen/silent are anagrams") }
	if IsAnagram("hello", "world") { t.Fatal("hello/world are not anagrams") }
	if IsAnagram("aab", "bba") { t.Fatal("aab/bba are not anagrams") }
}

func TestCountVowels(t *testing.T) {
	if got := CountVowels("umbrella"); got != 3 { t.Fatalf("want 3, got %d", got) }
	if got := CountVowels("AEIOU"); got != 5 { t.Fatalf("want 5, got %d", got) }
}
